public class UserInputProcessor {
    public String sanitizeAndExtract(String userInput) {
        if (userInput == null || userInput.isBlank()) {
            return "";
        }

        String cleaned = userInput.strip();  // Java 11+ Unicode-aware whitespace removal

        if (cleaned.length() > 100) {
            cleaned = cleaned.substring(0, 100);  // end index exclusive, returns exactly 100 chars
        }

        int atIndex = cleaned.indexOf("@");
        if (atIndex > 0) {
            String username = cleaned.substring(0, atIndex);
            return username.toLowerCase();
        }

        String[] words = cleaned.split("\\s+");  // regex pattern for one or more whitespace
        return String.join("-", words);
    }

    public boolean isValidCode(String code) {
        return code != null && code.length() == 6 && code.charAt(0) == 'X';
    }
}

public class StringFormatDemo {
    public static void main(String[] args) {
        // %s = string, %d = integer, %.2f = 2-decimal float
        String name = "Alice";
        int orders = 5;
        double total = 1234.5;
        String msg = String.format("%s placed %d orders worth $%.2f", name, orders, total);
        System.out.println(msg); // Alice placed 5 orders worth $1234.50

        // Padding/alignment: %-10s left-justifies in 10 cols, %05d zero-pads
        System.out.println(String.format("|%-10s|%05d|", "id", 42)); // |id        |00042|

        // formatted() is the Java 15+ instance shortcut for String.format
        String line = "Total: %,d".formatted(1000000); // Total: 1,000,000
        System.out.println(line);
    }
}

public class SubstringDemo {
    public void demonstrateExclusiveEnd() {
        String text = "HelloWorld";

        String first5 = text.substring(0, 5);  // end exclusive: "Hello" (5 chars)
        String last5 = text.substring(5);      // single arg: from 5 to end: "World"

        int length = first5.length();  // length = 5, exactly (5 - 0)

        String fullText = text.substring(0, text.length());  // valid: entire string
        // text.substring(0, text.length() + 1);  // WRONG: StringIndexOutOfBoundsException

        String email = "user@example.com";
        int atIndex = email.indexOf("@");
        if (atIndex > 0) {
            String username = email.substring(0, atIndex);  // from 0 to @, excluding @
            String domain = email.substring(atIndex + 1);   // from char after @ to end
            // no overlap, no gap — clean split
        }

        String csv = "apple,banana,cherry";
        int comma1 = csv.indexOf(",");
        int comma2 = csv.indexOf(",", comma1 + 1);
        String item2 = csv.substring(comma1 + 1, comma2);  // extracts "banana"
    }
}

public class ReplaceVsReplaceAll {
    public static void main(String[] args) {
        String s = "a.b.c.d";
        // replace(CharSequence, CharSequence): LITERAL text, no regex
        System.out.println(s.replace(".", "-"));       // a-b-c-d

        // replaceAll(String regex, String): first arg is a REGEX
        System.out.println(s.replaceAll("\\.", "-"));  // a-b-c-d (dot escaped)
        System.out.println(s.replaceAll(".", "-"));    // ------- ('.' matches any char)

        // Collapse runs of whitespace: a job for replaceAll, not replace
        String messy = "too   many    spaces";
        System.out.println(messy.replaceAll("\\s+", " ")); // too many spaces
    }
}

import java.util.regex.Pattern;

public class StringSplitExamples {
    public void demonstrateSplitBehavior() {
        String csv = "apple,banana,cherry";
        String[] fruits = csv.split(",");  // comma has no special regex meaning
        // fruits = ["apple", "banana", "cherry"]

        String filename = "report.2024.final.pdf";
        String[] wrongParts = filename.split(".");  // dot matches ANY character
        // wrongParts = ["", "", "", "", "", "", ...] — array of empty strings!

        String[] correctParts = filename.split("\\.");  // escaped dot for literal period
        // correctParts = ["report", "2024", "final", "pdf"]

        String trailingCommas = "a,b,c,,,";
        String[] dropped = trailingCommas.split(",");  // default behavior drops trailing empties
        // dropped = ["a", "b", "c"] — length 3, not 6

        String[] kept = trailingCommas.split(",", -1);  // negative limit keeps trailing empties
        // kept = ["a", "b", "c", "", "", ""] — length 6

        String userInput = "price|quantity";
        String safeSplit = Pattern.quote("|");  // escapes regex metacharacters
        String[] parts = userInput.split(safeSplit);
    }
}
